 return{enabled:true,age:s.age,activeInterestId:p.activeInterestId,summary:s.age<4?'Your first years belong to the people keeping you safe.':Object.keys(p.interests).length?'Not every afternoon needs to become a qualification.':'What do you enjoy when nobody is directing your future?',hobbies:Object.values(p.interests).map(h=>({...h,name:INTERESTS[h.id].name,description:INTERESTS[h.id].description,progress:h.practiceDays%6,lastPlayed:h.lastPracticeDay,active:h.id===p.activeInterestId})),pet,petHistory:p.petHistory.map(h=>({...h,species:PETS[h.species].name})),history:p.history.map(h=>({...h})),facts:[...p.facts],commitment:p.project?{title:p.project.title,completedDays:p.project.completedDays,totalDays:p.project.totalDays,remainingDays:p.project.remainingDays,locationId:p.project.locationId}:null,availableActions:pastimeActions(s)};
