 if(pet?.alive&&pet.deathDay>child.day){child.pastimes.pet={...pet,age:Math.max(0,Math.floor((child.day-pet.bornDay)/365)),bond:Math.min(40,pet.bond),caregiverId:child.age<18?caregiver(child)?.id||null:null};child.pastimes.facts.push(`inherited-pet:${pet.id}`);}
 // An heir keeps the animal, not their parent's learned hobbies or private afternoons.
