function actionScene(actionId,key,interestId){return actionId==='pet'?key==='pet_arrival':actionId==='petcare'?key==='pet_care':actionId==='practice'?!!INTERESTS[interestId]&&key.startsWith(`${interestId}_`):['fair','club','prank','skip','revision','games','night','crush','dinner','performance'].includes(actionId)&&key.startsWith(`${actionId}_`);}
const ACTIVITY_LIMITS={practice:3,fair:2,pet:1,petcare:4,club:2,prank:1,skip:1,revision:2,games:2,night:1,crush:1,dinner:2,performance:2};
